// Module 1 — Foundations of Computing
// Bloom's-aligned MCQs. Each topic follows the progression:
// Q1 Remember · Q2 Understand · Q3 Apply · Q4 Apply · Q5 Analyze · Q6 Evaluate · Q7 Create
// All distractors are Grade A: every option is plausible to a student who
// hasn't studied the topic. No joke options, no monkey-solvable choices.

export interface Question {
  q: string;
  opts: string[];
  ans: number;
  why: string;
  bloom?: "remember" | "understand" | "apply" | "analyze" | "evaluate" | "create";
}

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: Why Computers Were Invented (Speed, Accuracy, Storage, Connectivity) ───
  1: [
    { q: "Which set correctly lists the four foundational reasons computers were invented?", opts: ["Speed, Accuracy, Storage, Connectivity", "Processing, Memory, Display, Network", "Calculation, Automation, Communication, Simulation", "Input, Output, Storage, Connectivity"], ans: 0, why: "The four classical reasons are Speed, Accuracy, Storage, and Connectivity (S.A.S.C). The other options mix related concepts but are not the canonical four.", bloom: "remember" },
    { q: "A textbook claims: \"Accuracy just means computers are fast.\" What's wrong with this statement?", opts: ["Nothing — speed and accuracy are the same idea", "Accuracy refers to executing instructions without error, independent of how fast that execution is", "Accuracy only applies to mathematical calculations, not general computing", "Accuracy actually means how much storage a computer has"], ans: 1, why: "Speed is how many operations per second. Accuracy is whether those operations produce correct results. A slow calculator can still be accurate; a fast one can still be wrong.", bloom: "understand" },
    { q: "A hospital records 50,000 patient vitals per hour across wards and syncs them to a central dashboard for doctors working remotely. Which two of the four reasons most directly justify this system?", opts: ["Speed and Accuracy only", "Storage and Connectivity only", "Speed (real-time capture) and Connectivity (remote access for doctors)", "Accuracy and Storage only"], ans: 2, why: "Capturing vitals as they happen is Speed. Letting remote doctors see them is Connectivity. Storage and Accuracy matter too, but Speed + Connectivity are what make THIS scenario work.", bloom: "apply" },
    { q: "A university wants to keep 30 years of student records accessible from any campus branch. Which reason does this primarily demonstrate?", opts: ["Speed, because search must be fast", "Accuracy, because records must be correct", "Storage combined with Connectivity — retaining huge archives and making them reachable from any location", "Only Connectivity, since storage is handled by paper backups"], ans: 2, why: "Long retention is Storage. Multi-branch access is Connectivity. The scenario requires both working together, which is exactly why modern computers replaced paper archives.", bloom: "apply" },
    { q: "Two proposals solve the same payroll problem. Proposal A: a faster single computer. Proposal B: a slower computer connected to every branch office. Which of the four reasons are each proposal prioritising?", opts: ["A prioritises Speed; B prioritises Connectivity", "Both prioritise Speed equally", "A prioritises Accuracy; B prioritises Storage", "Neither can be explained with the four reasons"], ans: 0, why: "Proposal A buys raw throughput (Speed). Proposal B trades speed for the ability to share data across locations (Connectivity). Good analysis means naming the trade-off, not just picking a side.", bloom: "analyze" },
    { q: "A startup founder insists: \"Storage is the only reason that really matters — everything else is secondary.\" Evaluate this claim.", opts: ["Correct — without storage nothing else works", "Flawed — each of the four reasons solves a different human problem, and removing any one makes the others far less useful (e.g., stored data without connectivity is trapped)", "Correct — storage is the oldest reason and therefore the most important", "Flawed only because speed is actually the most important reason"], ans: 1, why: "The four reasons are complementary, not ranked. Storage without Connectivity is an isolated vault. Speed without Accuracy is fast garbage. Evaluating the claim means seeing the interdependence, not picking a winner.", bloom: "evaluate" },
    { q: "You're designing a computing system for a rural school with unreliable power and intermittent internet. Which design best balances the four reasons under these constraints?", opts: ["Prioritise raw Speed with the most powerful processor available", "Local Storage with offline caching + periodic Connectivity sync when internet is available; Accuracy via automated checks; Speed sized for actual workload", "Cloud-only system that requires constant Connectivity to function", "Paper-based system since computers can't work here"], ans: 1, why: "A good design weights the four reasons against the constraints. Power + internet are unreliable, so you lean on local Storage and opportunistic Connectivity. Speed and Accuracy still matter but are sized to the real workload, not maximised blindly.", bloom: "create" },
  ],

  // ─── Topic 2: Evolution of Computers (Mechanical → Electronic → PC → Mobile) ───
  2: [
    { q: "Which sequence correctly orders the four eras of computing from earliest to most recent?", opts: ["Electronic → Mechanical → Personal Computer → Mobile", "Mechanical → Electronic → Personal Computer → Mobile & Internet", "Mechanical → Personal Computer → Electronic → Mobile", "Personal Computer → Electronic → Mechanical → Mobile"], ans: 1, why: "The canonical order: Mechanical (gears, beads, no electricity) → Electronic (vacuum tubes, room-sized) → PC (desktops in homes) → Mobile & Internet (portable + always online).", bloom: "remember" },
    { q: "Why did the Electronic Era represent a genuine leap over the Mechanical Era, beyond just being \"newer\"?", opts: ["Electronic computers were cheaper to build than mechanical ones", "Using electricity for switching allowed thousands of operations per second, where mechanical gears were physically limited by friction and inertia", "Electronic computers were smaller than mechanical ones from day one", "Electronic computers had internet, mechanical ones did not"], ans: 1, why: "The substantive difference is physics. Moving electrons is orders of magnitude faster than moving gears. Size and cost improved much later; the speed jump was immediate and fundamental.", bloom: "understand" },
    { q: "You're shown a device that uses rotating wheels, no electricity, and is used to perform arithmetic. Which era does it belong to?", opts: ["Electronic Era — any calculator counts", "Mechanical Era — no electricity is the giveaway", "Personal Computer Era — it's a calculator", "Mobile Era — if it's small it must be modern"], ans: 1, why: "\"No electricity\" is the Mechanical Era signature. Wheels, gears, and beads (abacus, Pascaline, Babbage's machines) all sit in this era regardless of size.", bloom: "apply" },
    { q: "A museum labels ENIAC as belonging to the \"Personal Computer Era\" because it was used to solve specific problems. Is this label correct, and why?", opts: ["Yes — solving specific problems is what PCs do", "No — ENIAC was room-sized, used vacuum tubes, and cost millions; it belongs to the Electronic Era. PCs made computers affordable for individuals", "Yes — ENIAC was built in the 1940s, which is the PC era", "No — ENIAC belongs to the Mobile Era because of its global impact"], ans: 1, why: "Era classification is about technology and accessibility, not about purpose. ENIAC = vacuum tubes, rooms, millions of dollars = Electronic Era. PC Era means chips on a desk, affordable to households.", bloom: "apply" },
    { q: "Compare the PC Era to the Mobile & Internet Era. Which pair of improvements most cleanly distinguishes the Mobile Era from the PC Era?", opts: ["Bigger screens and louder speakers", "Portability (carry anywhere) and always-on Connectivity (internet built-in)", "Faster processors alone", "Colour displays, which PCs never had"], ans: 1, why: "PCs brought computers into homes but kept you at a desk. The Mobile Era's two defining shifts are you can take the computer with you (Portability) and it's always connected (Connectivity).", bloom: "analyze" },
    { q: "A historian argues: \"The Mobile Era is just the PC Era with smaller screens — nothing fundamental changed.\" Evaluate.", opts: ["Correct — smartphones are just tiny laptops", "Flawed — constant connectivity + location awareness + ubiquity changed how people use computing (banking, maps, social apps exist because of mobile, not in spite of it)", "Correct — nothing important has changed since the PC era", "Flawed only because smartphones have better cameras"], ans: 1, why: "A weak evaluation focuses on screen size. A strong evaluation names the qualitatively new capabilities — location, always-online, in-pocket — that created entire app categories impossible on a PC.", bloom: "evaluate" },
    { q: "Imagine the next era of computing (post-Mobile). Based on the pattern from Mechanical → Electronic → PC → Mobile, what's the most defensible prediction for its defining characteristic?", opts: ["Even smaller phones", "Computing that dissolves into the environment — ambient, wearable, or AI-mediated — where the user no longer consciously \"uses a computer\"", "A return to mechanical gears", "The same as the Mobile Era, just cheaper"], ans: 1, why: "Each era reduced the friction of accessing computing: rooms → desks → pockets → ???. The pattern suggests the next step is removing the device itself, with glasses, voice, or ambient AI taking its place.", bloom: "create" },
  ],

  // ─── Topic 3: Input → Process → Output (IPO) ───
  3: [
    { q: "Which expansion of IPO is correct?", opts: ["Internal Processing Operation", "Input, Process, Output", "Integrated Program Output", "Input, Protocol, Output"], ans: 1, why: "IPO = Input → Process → Output. Every computer operation in the world reduces to some version of this three-step cycle.", bloom: "remember" },
    { q: "Why is Output always placed after Process in the IPO cycle, never before?", opts: ["Tradition — the letters just happen to be in that order", "Output is the result of processing; there is nothing meaningful to output until the CPU has transformed the input", "Output devices need to boot up before processing starts", "Output is optional and therefore always last"], ans: 1, why: "The order reflects causality, not convention. Output depends on what Process produced. Reversing the order would be asking the computer to show an answer before computing it.", bloom: "understand" },
    { q: "You use a fingerprint to unlock your phone and the home screen appears. Map each action to an IPO stage.", opts: ["Fingerprint = Output, screen = Input", "Fingerprint = Input, matching algorithm = Process, home screen = Output", "Fingerprint = Process, home screen = Input", "All three steps happen at the home screen"], ans: 1, why: "Your finger touching the sensor is data going IN (Input). The phone comparing the print to the stored pattern is Process. The home screen appearing is the computer's response OUT (Output).", bloom: "apply" },
    { q: "An online banking transfer: you type an amount, the bank verifies the balance, and a confirmation message appears. Which step represents Process?", opts: ["Typing the amount", "The balance check and transfer logic running on the server", "The confirmation message appearing", "All of the above are input"], ans: 1, why: "Typing is Input. Message appearing is Output. The balance verification, limit checks, and ledger update on the server — all invisible to you — are the Process step.", bloom: "apply" },
    { q: "A student argues that Storage is \"just a kind of Output.\" Analyse whether this is correct.", opts: ["Correct — saving a file is output to the hard drive", "Partly — storage often follows processing, but it's better modelled as a fourth step because stored data can become Input again later, creating a cycle Output cannot", "Correct — storage and output are literally the same", "Wrong — storage has nothing to do with IPO at all"], ans: 1, why: "Output is what leaves the computer for the user. Storage is internal retention so data can feed back in tomorrow. Collapsing the two loses an important distinction: storage is a loop back to Input.", bloom: "analyze" },
    { q: "Two designers model a voice assistant. Designer A treats the entire interaction as one IPO cycle. Designer B treats it as a chain: (speech → text) → (text → intent) → (intent → answer) → (answer → audio), each its own IPO. Which model is more useful and why?", opts: ["A, because simpler is always better", "B, because decomposing into smaller IPO cycles reveals where failures happen and lets each stage be improved or replaced independently", "A, because voice assistants only have one process step", "Neither — IPO doesn't apply to voice assistants"], ans: 1, why: "Evaluating design quality means asking which model helps you debug, extend, and reason about the system. Nested IPO cycles expose bottlenecks; the single-cycle view hides them.", bloom: "evaluate" },
    { q: "Design the IPO flow for a smart traffic light at a busy intersection. What sensors (Input), logic (Process), and signals (Output) would you include?", opts: ["Just a timer that cycles every 30 seconds", "Input: cameras counting vehicles + pedestrian buttons + emergency-vehicle radio. Process: software balancing flow, pedestrian waits, and emergency priority. Output: signal lights + pedestrian walk signs + data to city dashboard", "Only output lights — no input needed", "Only the processor — sensors and lights are optional"], ans: 1, why: "A designed IPO system names real inputs, a real decision process, and multiple outputs. A timer-only light ignores reality; a sensor-free design can't adapt; a process-only system has nothing to work with.", bloom: "create" },
  ],

  // ─── Topic 4: CPU (Control Unit, ALU, Registers) ───
  4: [
    { q: "Which expansion and description of CPU is correct?", opts: ["Central Processing Unit — the hardware that executes instructions", "Common Program Utility — a piece of software that runs programs", "Core Processing Utility — a memory chip for frequently-used data", "Central Protocol Unit — the chip that manages network traffic"], ans: 0, why: "CPU = Central Processing Unit. It is hardware (not software), it executes instructions (not just stores them), and it handles computation (not networking).", bloom: "remember" },
    { q: "Within a CPU, why do the Control Unit and the ALU exist as separate components instead of being one unified block?", opts: ["Historical accident — no real reason", "Separation of concerns: the CU decides what to do and in what order; the ALU performs arithmetic and logic. Splitting them allows each to be optimised independently", "The ALU is faster than the CU, so they must be separate", "The CU is older technology that is being phased out"], ans: 1, why: "Splitting a 'decider' from a 'doer' is a classic engineering pattern. The CU fetches and routes; the ALU crunches numbers. Each can be scaled, pipelined, or replicated without disturbing the other.", bloom: "understand" },
    { q: "A program needs to check whether a user's balance minus a withdrawal is still greater than zero. Which CPU component performs BOTH the subtraction and the comparison?", opts: ["Control Unit, because it controls the logic", "ALU, because it handles arithmetic (subtraction) and logic (greater-than comparison) — the 'A' and 'L' in its name", "Registers, because they store the balance", "Main RAM, because the calculation happens there"], ans: 1, why: "Arithmetic Logic Unit literally means arithmetic AND logic. Subtract = arithmetic. 'Is result > 0?' = logic. Both live in the ALU.", bloom: "apply" },
    { q: "A program sums numbers in a tight loop a million times. Where does the CPU keep the running total for fastest access?", opts: ["On the hard drive, for safety", "In a CPU register, because registers are inside the CPU and far faster than RAM or storage for values being used right now", "In cloud storage, so it survives reboots", "In ROM, because ROM is fast"], ans: 1, why: "Registers sit inside the CPU and are measured in picoseconds. RAM is nanoseconds. Storage is milliseconds. For a value touched a million times per second, only a register is fast enough.", bloom: "apply" },
    { q: "A CPU is advertised as \"8-core at 2.4 GHz.\" Another as \"2-core at 4.8 GHz.\" A software engineer tells you: \"For a video-editing workstation running multiple parallel renders, pick the 8-core.\" Analyse why this is the right call.", opts: ["Because higher core count is always better", "Parallel renders can run independently on different cores; 8 cores × 2.4 GHz give more total throughput than 2 cores × 4.8 GHz, even though each individual core is slower", "Because 2.4 GHz is faster than 4.8 GHz", "Because the 8-core chip is newer and therefore better"], ans: 1, why: "Clock speed is per-core throughput. Cores are independent workers. When the workload parallelises (rendering multiple clips, compiling files), more workers beats faster workers. Analysis requires weighing workload shape against hardware shape.", bloom: "analyze" },
    { q: "A school is deciding between (A) 2 GHz quad-core CPUs and (B) 4 GHz single-core CPUs for classroom workstations that run a browser, a word processor, and a video chat simultaneously. Which is the better buy and why?", opts: ["B, because higher GHz is always better", "A, because running three applications at once benefits more from multiple independent cores than from one very fast core", "They are identical — GHz × cores is all that matters", "Neither — GHz is irrelevant to real performance"], ans: 1, why: "Evaluating real workloads means thinking about parallelism. Three apps running side by side is exactly the scenario where multiple cores pay off. A single 4 GHz core would bottleneck switching between them.", bloom: "evaluate" },
    { q: "Design a simplified CPU for a smart thermostat. What minimal set of components from {Control Unit, ALU, Registers, Cache} would you include, and why?", opts: ["Nothing — a thermostat doesn't need a CPU", "All four, identical to a gaming PC", "Control Unit + ALU + a handful of registers. Thermostats do light work (read temperature, compare to setpoint, toggle relay) so cache is overkill; CU directs flow, ALU compares numbers, registers hold the current reading", "Only registers — no logic needed"], ans: 2, why: "Designing for a thermostat means matching components to workload. Decision-making (CU) and comparison (ALU) are essential. Registers are essential. Large caches exist to hide RAM latency on big workloads — they add cost a thermostat doesn't need.", bloom: "create" },
  ],

  // ─── Topic 5: Memory (RAM vs ROM) ───
  5: [
    { q: "Which statement correctly describes RAM?", opts: ["Permanent storage for the operating system and your personal files", "Fast, volatile working memory — data vanishes when power is removed", "A type of hard drive with no moving parts", "Read-only chip containing startup instructions"], ans: 1, why: "RAM = Random Access Memory. It is fast (good), but volatile (data lost on power off). The last option describes ROM, not RAM.", bloom: "remember" },
    { q: "Why is ROM specifically used to hold boot instructions rather than RAM or the hard drive?", opts: ["ROM is faster than RAM", "ROM retains its contents without power, so the CPU has instructions to execute at the very instant power is applied — before any drive or RAM has been initialised", "ROM is cheaper per gigabyte than a hard drive", "ROM is newer technology than RAM"], ans: 1, why: "At power-on, RAM is blank and storage hasn't been accessed yet. Something has to tell the CPU what to do first. ROM is the only option that remembers its contents across power cycles AND is directly readable by the CPU.", bloom: "understand" },
    { q: "You're editing a 10-page document. The building loses power. After reboot, the last two pages are gone but the earlier pages (which you had saved 5 minutes ago) are intact. Explain what happened in memory terms.", opts: ["ROM lost its contents on power loss", "Saved pages were written to non-volatile storage (disk). The last two pages existed only in volatile RAM, which cleared when power cut", "The CPU forgot those pages", "Only the hard drive loses data on power cuts"], ans: 1, why: "The pattern \"lost everything since the last save\" is the signature of RAM volatility. Storage keeps data across power cuts; RAM does not. The \"save\" button moves data from RAM to storage.", bloom: "apply" },
    { q: "A smartphone spec sheet lists \"8 GB RAM, 256 GB storage.\" Your friend says \"the 256 is more important because it's bigger.\" What's more precise advice?", opts: ["Agree — bigger number always means better", "They do different jobs: 256 GB determines how many photos/apps you can KEEP; 8 GB determines how many you can USE AT ONCE without slowdown. Both matter, but for different reasons", "Disagree — only RAM matters", "They are the same kind of memory with different labels"], ans: 1, why: "Storage is long-term capacity. RAM is short-term concurrent working space. Giving good advice means naming both jobs instead of treating memory as a single number.", bloom: "apply" },
    { q: "A server is swapping heavily — the OS is moving data between RAM and disk constantly, and everything feels slow. Analyse the root cause.", opts: ["The CPU is broken", "The working set has exceeded physical RAM, so the OS uses disk as overflow (\"swap\"). Because disk is ~100,000× slower than RAM, performance collapses. Fix: more RAM, or reduce memory demand", "The hard drive is full", "Swap is a feature, not a problem, so nothing needs changing"], ans: 1, why: "The diagnostic signature is \"slow + heavy disk activity + high memory pressure.\" That's swap thrashing. Analysing means naming the mechanism (RAM overflow to disk) and the cause (working set > RAM).", bloom: "analyze" },
    { q: "A startup stores all customer orders \"only in RAM for speed\" and skips writing to disk. Evaluate this architectural choice.", opts: ["Good — RAM is faster so it's the right call", "Dangerous — a single power event, crash, or OS reboot wipes every order placed since the last start. Production systems need durable storage; RAM is a cache, not a source of truth", "Good — disks are obsolete", "Dangerous only if the RAM is small"], ans: 1, why: "Evaluating requires weighing the benefit (speed) against the risk (data loss on any restart). For a customer-order system the loss is catastrophic. The right pattern is RAM for speed PLUS disk/DB for durability.", bloom: "evaluate" },
    { q: "Design the memory configuration for a 4K video-editing workstation that will run Premiere Pro, Chrome with 20 tabs, and two preview monitors. Justify each choice.", opts: ["8 GB RAM + 256 GB HDD — save money", "32–64 GB RAM (large working set for 4K frames + many apps) + 1–2 TB NVMe SSD (fast project reads/writes, durable) + keep ROM stock. HDD-only would bottleneck the editor", "64 GB ROM and skip RAM entirely", "Only cloud storage — no local memory needed"], ans: 1, why: "Design means matching capacity to workload. 4K editing has huge working sets (RAM) and huge file I/O (fast SSD). Justification should mention both dimensions; an HDD or ROM-centric answer reveals the student doesn't understand the role of each memory type.", bloom: "create" },
  ],

  // ─── Topic 6: Input Devices ───
  6: [
    { q: "Which of the following is the correct definition of an input device?", opts: ["Any device plugged into the computer via USB", "A device that sends data or instructions INTO the computer from the user or environment", "A device that displays processed results to the user", "A device that stores data permanently"], ans: 1, why: "\"Input\" is directional: data flows IN. USB is a port, not a direction. Displays are output. Storage is a separate role.", bloom: "remember" },
    { q: "Why are touchscreens classified as input/output (I/O) devices rather than purely input or purely output?", opts: ["Because they are expensive", "Because they simultaneously display content (output) and register touch (input) through the same surface", "Because they require a driver", "Because they can be turned off"], ans: 1, why: "The classification is about what data flows through the device. A touchscreen both shows pixels (out) and reports finger positions (in), so it plays both roles — hence I/O.", bloom: "understand" },
    { q: "A food delivery driver scans a QR code with their phone camera to mark a parcel delivered. The camera is serving as what kind of device here?", opts: ["Output device, because it's displaying the QR code", "Input device, because it's capturing image data and feeding it into the app for decoding", "Processing device, because it decodes the QR", "Storage device, because the image is saved"], ans: 1, why: "The camera is the sensor that pulls the QR pattern into the phone. Decoding happens in the processor afterwards. Direction-of-data-flow = Input.", bloom: "apply" },
    { q: "A graphic designer uses a pressure-sensitive stylus on a drawing tablet. Which of the following best captures WHY this is an input device, not just a pointer?", opts: ["It moves the cursor", "It transmits multiple streams of data (position, pressure, tilt, sometimes rotation) into the computer — richer input than a standard mouse", "It has a battery", "It only works with certain software"], ans: 1, why: "Applying the definition means identifying what goes IN. A stylus feeds position + pressure + tilt simultaneously. That richness is why designers prefer it over a mouse, which feeds only position and buttons.", bloom: "apply" },
    { q: "A voice assistant mis-transcribes \"book a meeting at four\" as \"book a meeting at for.\" Analyse where in the input pipeline the error likely occurred.", opts: ["The microphone is broken", "The microphone (physical input) likely captured the audio correctly; the error is downstream in the speech-to-text model (processing), which chose a homophone. Input hardware vs. processing logic are different layers", "The speakers are wrong", "The hard drive corrupted the file"], ans: 1, why: "Distinguishing input (audio captured) from processing (audio interpreted) is core analysis. A replaced microphone would not fix \"four\" vs \"for\" — that's a language-model issue, not a hardware issue.", bloom: "analyze" },
    { q: "For a public library's self-checkout kiosk used by elderly patrons, which primary input method is best and why?", opts: ["Keyboard only — cheapest", "Large touchscreen with barcode scanner + optional voice prompts — accessible to users with varying dexterity, literacy, and vision, while the scanner speeds up the common task", "Gesture recognition via webcam — futuristic", "Mouse and trackball — traditional"], ans: 1, why: "Evaluating input choices means weighing the user population. Elderly patrons benefit from large targets (touchscreen), fewer typed characters (barcode), and alternative modes (voice). A keyboard-only kiosk optimises for the wrong user.", bloom: "evaluate" },
    { q: "Design the input system for a hospital operating theatre where surgeons' hands must stay sterile. Which inputs would you use, and why does a standard keyboard/mouse not fit?", opts: ["Standard keyboard and mouse", "Foot pedals + voice commands + gesture sensors + pre-surgery touchscreen setup — all minimise physical contact after scrub-in; keyboards/mice can't be sterilised reliably and require hand use the surgeon needs for instruments", "A microphone alone, no other input", "No inputs — surgeons don't need computers"], ans: 1, why: "Designing for a constraint (sterility, hands busy) means choosing inputs that honour it. Hands-free modalities (foot, voice, gesture) exist precisely for scenarios keyboards can't serve.", bloom: "create" },
  ],

  // ─── Topic 7: Output Devices ───
  7: [
    { q: "Which of the following is the correct definition of an output device?", opts: ["Any device that requires electricity", "A device that communicates processed results from the computer to the user or environment", "A device that captures user actions", "A device that connects to the internet"], ans: 1, why: "Output is directional — data flows OUT of the computer. Electricity use, action capture (input), and networking are separate concerns.", bloom: "remember" },
    { q: "What is the meaningful difference between a \"hard copy\" and a \"soft copy\" of a document?", opts: ["Hard copies are more accurate", "Soft copies exist as digital data (screen, file); hard copies exist as physical matter (ink on paper). They are two different output media, not two qualities of the same thing", "Hard copies are always bigger", "Soft copies cannot be shared"], ans: 1, why: "The distinction is the medium, not the content. The same essay can be both. Hard = physical and permanent in form. Soft = digital and easy to edit/share.", bloom: "understand" },
    { q: "A phone vibrates when a message arrives. Classify the vibration.", opts: ["Input — the phone is sensing something", "Output — the phone is communicating a state (new message) to the user, even if no screen or sound is used", "Processing — the CPU is working", "Storage — the message is saved"], ans: 1, why: "Haptic feedback is the computer telling YOU something. That's output by definition — the medium (motion) is unusual, but the direction of information flow is the same as a screen or speaker.", bloom: "apply" },
    { q: "A student claims: \"The monitor shows output, so if I can see it on the screen, it's output — end of story.\" Apply the definition: is a cursor moving in response to the mouse output?", opts: ["No — cursor motion is input because the mouse is input", "Yes — the cursor's position on screen is rendered by the GPU and displayed on the monitor, which is output. The mouse is input; the cursor is the visualised result of processing the mouse input", "It's neither — cursors are special", "Only if the mouse has a light"], ans: 1, why: "Input and output are defined by direction, not by source. The mouse sends data IN. The cursor appears OUT. They're two ends of a single IPO cycle.", bloom: "apply" },
    { q: "A projector, a monitor, and a printer all present the same slide deck. Analyse which dimensions (audience size, permanence, colour fidelity, cost per use) each optimises.", opts: ["They're all identical", "Projector = large audience, temporary, lower fidelity, low cost per use. Monitor = small audience, temporary, high fidelity, low cost. Printer = any audience, permanent, high fidelity, high cost per copy. Each is optimal for a different output goal", "Only printers matter", "Only monitors matter"], ans: 1, why: "Real analysis maps each device onto trade-offs rather than ranking them. \"Which output device\" depends on audience, permanence, fidelity, and cost per use — different combinations make different devices right.", bloom: "analyze" },
    { q: "A small business must choose ONE output for invoices: printer, PDF export (screen/email), or both. Evaluate.", opts: ["Printer only — paper is professional", "Both — PDF (fast, free to duplicate, searchable, archivable) is the primary output; printer is an on-demand fallback for customers who need paper. PDF-only may fail for some legal/tax scenarios", "PDF only — always cheaper", "Neither — invoices aren't important"], ans: 1, why: "Evaluating means weighing cost, speed, legal needs, and customer preference. The answer \"both, but digital as default\" recognises PDF is strictly more versatile while accepting paper's niche.", bloom: "evaluate" },
    { q: "Design the output system for a self-driving car. Which outputs are necessary to serve both the passengers AND the environment around the car?", opts: ["A single dashboard screen", "Passenger outputs: dashboard + voice + haptics. Environment outputs: headlights + indicators + horn + brake lights + (possibly) external signals for pedestrians. Both audiences need to know what the car is doing", "Only headlights — nothing else", "Only speakers for music"], ans: 1, why: "Designing means mapping outputs to each audience. A car communicates with occupants AND with drivers/pedestrians around it. Skipping either audience (dash-only, or lights-only) makes the system unsafe or useless.", bloom: "create" },
  ],

  // ─── Topic 8: Storage (HDD, SSD, USB, Cloud) ───
  8: [
    { q: "Which statement about secondary storage is correct?", opts: ["It is volatile — contents are lost when power is removed", "It is non-volatile — contents persist across power cycles, and it's where files and applications live long-term", "It replaces the CPU during boot", "It is the same physical chip as RAM"], ans: 1, why: "Secondary storage (HDD, SSD, USB, cloud-backed disks) is non-volatile. That's precisely what distinguishes it from RAM (primary, volatile) and why your files are still there after you restart.", bloom: "remember" },
    { q: "Why is an SSD typically faster than an HDD for opening large applications, even when both have the same capacity?", opts: ["SSDs are physically larger, so they hold more", "HDDs have a spinning disk and a read head that must physically seek to each location (milliseconds); SSDs read from flash chips electronically (microseconds)", "SSDs have better internet connections", "HDDs need to warm up before reading"], ans: 1, why: "The gap is mechanical vs electronic access. Moving a physical head is slow on a human scale; reading from silicon isn't. This is why boot times dropped from 60 s to 10 s when laptops switched to SSD.", bloom: "understand" },
    { q: "You're backing up family photos and need them accessible from your laptop at home, your phone on trips, and your parents' computer. Which storage approach fits this need?", opts: ["A single USB drive kept in a drawer", "Cloud storage (e.g., Google Drive / iCloud) with a local copy on the laptop — reachable from any device with internet, plus offline access on the primary machine", "A hard drive in a locked safe", "Only the phone's internal storage"], ans: 1, why: "The scenario's keyword is multi-device access. Cloud storage is specifically designed for that. Applying storage knowledge means matching the scenario (multi-device) to the medium's strength (internet-accessible).", bloom: "apply" },
    { q: "A photographer has 2 TB of RAW files. She edits a small \"current project\" (~50 GB) daily and archives the rest. Which storage layout fits her workflow?", opts: ["Keep everything on one HDD", "Fast SSD for OS + current project (speed during editing) + large HDD or NAS for archive (cheaper per GB, slower access is fine for rarely-touched files) + cloud backup", "Keep everything on a USB stick", "Cloud only — no local copies"], ans: 1, why: "Applying storage hierarchy means placing hot data on fast media and cold data on cheap media. This \"tiered storage\" pattern is standard — and why professional workstations usually have both SSD and HDD.", bloom: "apply" },
    { q: "A university department backs up all research only to a single external hard drive kept next to the server. Analyse the risks.", opts: ["No risks — external drives are reliable", "Single point of failure: theft, fire, drive failure, or ransomware on the server can destroy both copies simultaneously. The 3-2-1 rule (3 copies, 2 media, 1 off-site) addresses this", "The only risk is drive size", "External drives can't hold research data"], ans: 1, why: "Analysing backups means naming failure modes that defeat the whole strategy at once. Co-located backups are defeated by any physical or network-wide incident. Off-site and/or offline copies break that correlation.", bloom: "analyze" },
    { q: "A small business can afford ONE storage upgrade: (A) bigger HDD, (B) same-size SSD, (C) cloud subscription. They run Excel-heavy accounting and occasional video calls. Evaluate.", opts: ["A — more space is always better", "B — their workload is limited by disk speed (opening/saving files), not capacity. An SSD gives immediate daily-use improvement. Cloud is useful but doesn't fix local latency", "C — cloud is always best", "None — skip the upgrade"], ans: 1, why: "Evaluating means matching the bottleneck to the solution. \"We run out of space\" → bigger disk. \"Everything is slow\" → faster disk. Accounting on spinning drives is typically speed-bound, making SSD the highest-leverage upgrade.", bloom: "evaluate" },
    { q: "Design a storage strategy for a wedding photographer delivering 50,000 photos per year to clients. Name the media, the redundancy, and why each layer exists.", opts: ["One external drive, no backup", "Local: fast SSD for current job (edit speed) + large HDD for archive (capacity). Backup: second HDD off-site + cloud backup (geographic + medium diversity). Client delivery: cloud gallery links. Each layer serves speed, archival capacity, disaster recovery, or delivery", "Only a USB stick", "Only cloud, no local storage"], ans: 1, why: "Designing storage means justifying every layer against a real risk or workflow. Speed, capacity, redundancy, and client-facing delivery are distinct jobs — a single medium can't do them all well.", bloom: "create" },
  ],

  // ─── Topic 9: Software (System, Application, Utility) ───
  9: [
    { q: "Which statement best distinguishes system software from application software?", opts: ["System software is paid; application software is free", "System software manages the hardware and provides services (OS, drivers); application software is built for end-user tasks (Word, Chrome, Spotify)", "System software is older than application software", "They are different names for the same thing"], ans: 1, why: "The distinction is role, not price or age. System software is the foundation the hardware talks to. Application software sits on top and serves the user directly.", bloom: "remember" },
    { q: "Why can't an application like WhatsApp run on a phone with no operating system installed?", opts: ["WhatsApp is too heavy", "Applications call into OS services (file system, network, screen, permissions). With no OS, those services don't exist, so the app has nothing to call and no way to reach the hardware", "WhatsApp needs a SIM card only", "Applications can actually run without an OS"], ans: 1, why: "Understanding software layering means seeing that applications are NOT self-contained programs on the hardware — they depend on the OS. No OS = no file access, no network, no screen, no app.", bloom: "understand" },
    { q: "An antivirus program scans for malicious files, removes them, and monitors new downloads. Which category of software is it?", opts: ["System software — it talks to hardware", "Utility software — it maintains the health and security of the computer without being the OS or a user-facing productivity app", "Application software — it's a user app", "None of the above"], ans: 1, why: "Applying the three-category model: OS = system. Maintenance/security tools = utility. Word, Excel, Chrome = application. Antivirus is a classic utility.", bloom: "apply" },
    { q: "A user complains, \"My computer is slow.\" Which category of software is the FIRST place to look — and what would you check?", opts: ["Application only — must be Chrome", "Start broad: check system (OS updates, drivers), then utility (malware scan, cleanup), then applications (which single app is consuming resources). Most performance issues resolve at one of these layers", "Ignore it — computers are just slow", "Reinstall Windows immediately"], ans: 1, why: "Applying the three-category model diagnostically gives a structured checklist. Slowness can come from any layer, but a systematic walk (system → utility → application) is faster than guessing.", bloom: "apply" },
    { q: "A company bans utility software (cleanup tools, antivirus from third parties) but keeps system and application software. Analyse the likely consequences.", opts: ["No consequences", "Over time: malware risk rises, disk clutter accumulates, performance drifts down. The OS has some built-in utilities, but dropping the category entirely leaves maintenance gaps that neither system nor application software covers", "The computers will run faster", "Applications will stop working immediately"], ans: 1, why: "Analysing means tracing consequences through the system. Utility is the maintenance layer. Remove it and the machine degrades slowly rather than failing instantly — which is worse, because the decline is harder to attribute.", bloom: "analyze" },
    { q: "A small business's IT budget allows ONE of: upgraded OS, new office-app licences, or a security/backup utility suite. Evaluate their priorities.", opts: ["Always pick the OS", "It depends on failure modes. If the current OS is unsupported (no security patches), upgrade the OS. If apps block real work, licence the apps. If there's no backup or antivirus, the utility suite prevents catastrophic loss. Rank by risk, not category", "Always pick applications", "Always pick utilities"], ans: 1, why: "Evaluating requires a risk-based ranking, not a default answer. An unsupported OS is a ticking time bomb. No backup is a bigger bomb. Old apps are annoying but non-catastrophic. The right answer names the criteria.", bloom: "evaluate" },
    { q: "Design the software stack for a school computer lab of 30 machines used for mixed coursework (writing, programming, research). Name one product in each category and justify.", opts: ["Just install Windows", "System: Linux or Windows (multi-user, manageable). Application: LibreOffice/Word + VS Code + Chrome (covers writing, programming, research). Utility: centrally-managed antivirus + automated backup + disk-cleanup tools. Justified by actual student tasks + shared-machine reality", "Just install Microsoft Word", "No software needed — just hardware"], ans: 1, why: "Designing a software stack means picking ONE representative from each category and connecting each choice to a real user need. An OS-only answer misses the apps students need; an app-only answer misses the shared-machine hygiene that utilities provide.", bloom: "create" },
  ],

  // ─── Topic 10: Internet Basics (IP, URL, DNS, Email) ───
  10: [
    { q: "Which statement correctly distinguishes an IP address from a URL?", opts: ["They are the same thing with different names", "An IP address is a numeric identifier for a device on the network (e.g., 142.250.190.46); a URL is a human-readable address for a resource (e.g., google.com/search). DNS translates URLs to IP addresses", "A URL is for email; IP is for websites", "Only URLs work on phones"], ans: 1, why: "IP = numeric address for a device. URL = readable locator for a resource. DNS bridges the two by converting names to numbers.", bloom: "remember" },
    { q: "Why does DNS exist at all — why not just memorise IP addresses?", opts: ["IP addresses don't actually exist without DNS", "Humans are bad at numbers but good at names. DNS gives us a stable name for a service whose IP can change. Without DNS, every IP change would break every bookmark", "DNS makes the internet faster", "IPs are secret and must be hidden"], ans: 1, why: "Understanding DNS means seeing it as a layer of indirection that serves two purposes: memorability (names) and flexibility (IPs can change behind the scenes without users noticing).", bloom: "understand" },
    { q: "You type `www.library.edu` into a browser. Put these steps in the correct order: (1) browser requests the page from the server, (2) DNS returns the IP address, (3) browser asks the DNS server for the IP of library.edu, (4) server sends the HTML back.", opts: ["1 → 2 → 3 → 4", "3 → 2 → 1 → 4", "4 → 3 → 2 → 1", "2 → 3 → 4 → 1"], ans: 1, why: "Applying your knowledge: the browser can't talk to a server until it has an IP. So: ask DNS (3) → receive IP (2) → request page (1) → receive HTML (4).", bloom: "apply" },
    { q: "Your friend says: \"Email and a URL are the same because they both have dots and letters.\" Correct her precisely.", opts: ["Agree — they are identical", "Disagree: an email address `name@domain.com` identifies a mailbox AT a domain; a URL like `https://domain.com/path` identifies a resource ON a server. Different purposes, different structures (@ vs /), different protocols (SMTP vs HTTP)", "Disagree — emails don't have dots", "Agree — there's no real difference"], ans: 1, why: "Applying the definitions surfaces three concrete differences: structure (@ vs /), purpose (mailbox vs resource), and protocol (mail vs web). Dots-and-letters is a surface-level similarity that hides the real distinction.", bloom: "apply" },
    { q: "Global DNS outage: all DNS servers go dark for an hour. Analyse which of the following would still work: (a) typing google.com, (b) visiting a site by IP address you've memorised, (c) sending email to friend@gmail.com.", opts: ["All would work", "Only (b). Typing a domain needs DNS to resolve it. Sending email needs DNS to find gmail.com's mail servers. A direct-IP visit bypasses DNS entirely", "Only (a) would work", "None would work"], ans: 1, why: "Analysing the outage means tracing which actions require DNS. Any action that starts with a name fails. An action that starts with an IP succeeds — because DNS was the only missing layer.", bloom: "analyze" },
    { q: "A teacher tells students: \"For privacy, always visit websites by IP address instead of URL.\" Evaluate.", opts: ["Good advice — IPs hide your identity", "Flawed — using IPs does NOT improve privacy: your ISP still sees where you connect, the site still logs you, and you lose the ability to verify HTTPS certificates (issued to domain names). It's security theatre", "Good advice — URLs are insecure", "Flawed only because IPs are hard to memorise"], ans: 1, why: "Evaluating technical advice requires checking whether the mechanism actually achieves the goal. Using IPs doesn't hide traffic (ISP sees the IP) and actively breaks HTTPS verification. The claim fails on its own terms.", bloom: "evaluate" },
    { q: "Design a minimal checklist a student can use to safely identify whether a URL they received in an email is legitimate (e.g., `secure-bank.example.com` vs `secure-bank-example.com.bad.ru`).", opts: ["Click it and see what happens", "1) Read the URL right-to-left — the real domain is the part just before the FIRST single slash. 2) Check the TLD (.com vs .ru). 3) Look for HTTPS + certificate name matching the domain. 4) Hover before clicking. 5) When unsure, go to the site directly via your bookmark, not the link", "Trust anything ending in .com", "Only check the sender's name"], ans: 1, why: "Designing a checklist means producing steps that catch real phishing techniques (subdomain spoofing, homoglyph domains, unexpected TLDs). A one-step answer (\"look at the URL\") isn't actionable; a real checklist is.", bloom: "create" },
  ],

  // ─── Topic 11: Internet Applications (Email, IM, Video Conferencing) ───
  11: [
    { q: "Which is the most accurate characterisation of email as a communication medium?", opts: ["Real-time casual messaging", "Asynchronous, formal, supports attachments, leaves a searchable record", "Live audio/video only", "Identical to instant messaging"], ans: 1, why: "Email's signature properties are asynchronous delivery, formal tone conventions, attachments, and a durable searchable record. That's what distinguishes it from IM and video calls.", bloom: "remember" },
    { q: "Why is email still preferred over instant messaging for formal business communication, despite IM being faster?", opts: ["Email is always cheaper", "Email's slower, asynchronous nature fits formal use: recipients can reply thoughtfully, attachments and audit trails are standard, and the format signals seriousness in a way a chat bubble does not", "IM doesn't support text", "Email is newer technology"], ans: 1, why: "Understanding the trade-off means seeing that \"faster\" isn't the only metric. For contracts, records, or deliberate responses, asynchronous beats real-time. Different media for different conversations.", bloom: "understand" },
    { q: "Choose the most appropriate tool for each task: (a) asking a classmate one quick question, (b) submitting a term paper to a professor, (c) a 30-minute project discussion with 4 remote team members.", opts: ["Email for all three", "(a) IM, (b) Email with attachment, (c) Video conferencing", "IM for all three", "Video conferencing for all three"], ans: 1, why: "Applying medium-fit: IM for quick casual, email for formal submission + record, video for multi-party discussion. Using one tool for everything wastes time or under-serves the task.", bloom: "apply" },
    { q: "A remote team schedules a daily 1-hour video call for standup. Apply what you know about media fit — what's likely going wrong?", opts: ["Nothing — daily video is best", "Video conferencing is expensive (time + attention). Standups are short, status-oriented updates best suited to async text (email digest, IM standup channel). 5 people × 1 hour = 5 hours/day burned", "The internet is the problem", "They need longer meetings"], ans: 1, why: "Applying media-fit analysis means recognising that synchronous video is overkill for short, predictable updates. Async channels (email, IM thread) recover everyone's morning while keeping the status flow.", bloom: "apply" },
    { q: "Analyse why a \"reply all\" on a 200-person email thread is usually considered harmful.", opts: ["Email servers can't handle it", "Every reply goes to all N recipients, so even a handful of reply-alls cascades into hundreds of messages — flooding inboxes and burying the replies that actually matter. The tool supports it, but the social contract penalises unnecessary broadcast — a mismatch of technical capability and communication norm", "There's nothing wrong with it", "Reply-all is always required by etiquette"], ans: 1, why: "Analysing means separating what the tool CAN do from what it SHOULD do. Reply-all is technically cheap but socially expensive, and the mismatch is the root of the complaint.", bloom: "analyze" },
    { q: "Your university is deciding between mandating Zoom for all classes vs mixing Zoom (live lectures) with email (assignments) and an IM tool like Slack (quick Q&A). Evaluate.", opts: ["Zoom-only is simpler and therefore better", "A mix is strictly better: each medium matches its content (live explanation = Zoom, written deliverables = email, ambient questions = IM). Zoom-only forces async tasks into a synchronous tool, wasting time and frustrating students who can't always be live", "Email-only is fine", "All three are equally bad"], ans: 1, why: "Evaluating means comparing how well each option fits the actual workload. Classes contain multiple communication types; forcing one medium onto all of them is a category error.", bloom: "evaluate" },
    { q: "Design a communication policy for a 20-person hybrid startup. Specify which medium to use for: (a) urgent outages, (b) weekly planning, (c) legal/formal communication, (d) ad-hoc questions, (e) onboarding new hires.", opts: ["Use Slack for everything", "(a) Phone call + IM page, (b) Video call + shared doc, (c) Email with signed attachments, (d) IM channel, (e) Video call + written handbook + IM mentor. Each medium chosen for urgency, formality, and record-keeping", "Use email for everything", "No policy needed"], ans: 1, why: "Designing a policy means mapping situations to media on explicit axes (urgency, formality, record). A blanket answer (\"everything on Slack\") fails because the axes conflict — urgent ≠ formal ≠ archival.", bloom: "create" },
  ],
};
